import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface CodeFile {
  name: string;
  path: string;
  content: string;
  language: string;
  size: number;
}

export interface FunctionAnalysis {
  name: string;
  type: 'UI' | 'Logic' | 'API' | 'Database' | 'Utility' | 'Unknown';
  snippet: string;
}

export interface FileAnalysisResult {
  fileName: string;
  language: string;
  functionCount: number;
  functions: FunctionAnalysis[];
  linesOfCode: number;
}

export interface AppIdea {
  title: string;
  description: string;
  relevanceScore: number;
  keyFeatures: string[];
  techStack: string[];
}

export interface AnalysisSummary {
  totalFiles: number;
  totalFunctions: number;
  languageDistribution: Record<string, number>;
  functionTypeDistribution: Record<string, number>;
  topFiles: FileAnalysisResult[];
}

import { CodeFile, FileAnalysisResult, FunctionAnalysis } from '../types';

const LANGUAGE_MAP: Record<string, string> = {
  'js': 'JavaScript',
  'jsx': 'JavaScript React',
  'ts': 'TypeScript',
  'tsx': 'TypeScript React',
  'py': 'Python',
  'java': 'Java',
  'kt': 'Kotlin',
  'cpp': 'C++',
  'c': 'C',
  'swift': 'Swift',
  'go': 'Go',
  'dart': 'Dart'
};

const FUNCTION_REGEXES = {
  JavaScript: /(?:function\s+([a-zA-Z0-9_$]+)|const\s+([a-zA-Z0-9_$]+)\s*=\s*(?:async\s*)?\([^)]*\)\s*=>)/g,
  TypeScript: /(?:function\s+([a-zA-Z0-9_$]+)|const\s+([a-zA-Z0-9_$]+)\s*=\s*(?:async\s*)?\([^)]*\)\s*=>|public\s+([a-zA-Z0-9_$]+)\s*\(|private\s+([a-zA-Z0-9_$]+)\s*\(|protected\s+([a-zA-Z0-9_$]+)\s*\()/g,
  Python: /def\s+([a-zA-Z0-9_$]+)\s*\(/g,
  Java: /(?:public|private|protected|static|\s) +[\w\<\>\[\]]+\s+([a-zA-Z0-9_$]+)\s*\([^\)]*\)\s*\{/g,
  Kotlin: /fun\s+([a-zA-Z0-9_$]+)\s*\(/g,
};

export function detectLanguage(fileName: string): string {
  const ext = fileName.split('.').pop()?.toLowerCase() || '';
  return LANGUAGE_MAP[ext] || 'Unknown';
}

export function analyzeFile(file: CodeFile): FileAnalysisResult {
  const language = detectLanguage(file.name);
  const lines = file.content.split('\n');
  const functions: FunctionAnalysis[] = [];

  const regex = (FUNCTION_REGEXES as any)[language];
  if (regex) {
    let match;
    while ((match = regex.exec(file.content)) !== null) {
      const name = match[1] || match[2] || match[3] || match[4] || match[5] || 'anonymous';

      // Heuristic for type categorization
      let type: FunctionAnalysis['type'] = 'Utility';
      const lowercaseContent = file.content.toLowerCase();
      const lowercaseName = name.toLowerCase();

      if (lowercaseName.includes('render') || lowercaseName.includes('view') || lowercaseContent.includes('ui') || lowercaseContent.includes('style')) {
        type = 'UI';
      } else if (lowercaseName.includes('get') || lowercaseName.includes('fetch') || lowercaseName.includes('api') || lowercaseContent.includes('http')) {
        type = 'API';
      } else if (lowercaseName.includes('save') || lowercaseName.includes('db') || lowercaseName.includes('query') || lowercaseContent.includes('sql')) {
        type = 'Database';
      } else if (lowercaseName.includes('calculate') || lowercaseName.includes('process') || lowercaseName.includes('handle')) {
        type = 'Logic';
      }

      functions.push({
        name,
        type,
        snippet: file.content.substring(match.index, match.index + 200) + '...'
      });
    }
  }

  return {
    fileName: file.name,
    language,
    functionCount: functions.length,
    functions,
    linesOfCode: lines.length
  };
}

import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisSummary, AppIdea } from "../types";

export async function generateAppIdeas(summary: AnalysisSummary): Promise<AppIdea[]> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    I have analyzed a codebase with the following statistics:
    - Total Files: ${summary.totalFiles}
    - Total Functions Found: ${summary.totalFunctions}
    - Languages Used: ${JSON.stringify(summary.languageDistribution)}
    - Function Types Breakdown: ${JSON.stringify(summary.functionTypeDistribution)}

    Based on these code snippets (which include ${summary.functionTypeDistribution['UI'] || 0} UI components, ${summary.functionTypeDistribution['API'] || 0} API integrations, and ${summary.functionTypeDistribution['Database'] || 0} data handlers), 
    suggest 4-5 highly relevant Android application ideas that could be built using or extending these functionalities.

    For each idea, provide:
    1. A catchy title.
    2. A detailed description.
    3. A relevance score (0-100) based on how well the existing snippets support it.
    4. Key features that would use the existing logic.
    5. Recommended tech stack (e.g., Kotlin, Jetpack Compose, Retrofit, Room).
  `;

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            description: { type: Type.STRING },
            relevanceScore: { type: Type.NUMBER },
            keyFeatures: { 
              type: Type.ARRAY,
              items: { type: Type.STRING }
            },
            techStack: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            }
          },
          required: ["title", "description", "relevanceScore", "keyFeatures", "techStack"]
        }
      }
    }
  });

  try {
    return JSON.parse(response.text);
  } catch (error) {
    console.error("Failed to parse Gemini response", error);
    return [];
  }
}

import React, { useState, useRef, useMemo } from 'react';
import { 
  FileCode, 
  FolderOpen, 
  BarChart3, 
  Lightbulb, 
  Cpu, 
  Layout, 
  Code2, 
  AlertCircle,
  Loader2,
  ChevronRight,
  Settings2,
  Layers
} from 'lucide-react';
import { 
  PieChart, 
  Pie, 
  Cell, 
  ResponsiveContainer, 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  Tooltip, 
  Legend 
} from 'recharts';
import { CodeFile, FileAnalysisResult, AnalysisSummary, AppIdea } from './types';
import { analyzeFile } from './services/codeParser';
import { generateAppIdeas } from './services/geminiService';

const COLORS = ['#6366f1', '#a855f7', '#ec4899', '#f43f5e', '#8b5cf6', '#06b6d4'];

export default function App() {
  const [files, setFiles] = useState<CodeFile[]>([]);
  const [analyzing, setAnalyzing] = useState(false);
  const [generating, setGenerating] = useState(false);
  const [analysisResults, setAnalysisResults] = useState<FileAnalysisResult[]>([]);
  const [appIdeas, setAppIdeas] = useState<AppIdea[]>([]);
  const [error, setError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const fileList = e.target.files;
    if (!fileList || fileList.length === 0) return;

    setAnalyzing(true);
    setError(null);
    const newFiles: CodeFile[] = [];

    try {
      for (let i = 0; i < fileList.length; i++) {
        const file = fileList[i];
        const content = await file.text();
        newFiles.push({
          name: file.name,
          path: (file as any).webkitRelativePath || file.name,
          content,
          language: file.name.split('.').pop() || 'txt',
          size: file.size
        });
      }

      setFiles(newFiles);
      const results = newFiles.map(analyzeFile);
      setAnalysisResults(results);
    } catch (err) {
      setError("Failed to read files. Please try again.");
      console.error(err);
    } finally {
      setAnalyzing(false);
    }
  };

  const summary = useMemo<AnalysisSummary | null>(() => {
    if (analysisResults.length === 0) return null;

    const langDist: Record<string, number> = {};
    const funcTypeDist: Record<string, number> = {};
    let totalFuncs = 0;

    analysisResults.forEach(res => {
      langDist[res.language] = (langDist[res.language] || 0) + 1;
      totalFuncs += res.functionCount;
      res.functions.forEach(f => {
        funcTypeDist[f.type] = (funcTypeDist[f.type] || 0) + 1;
      });
    });

    return {
      totalFiles: analysisResults.length,
      totalFunctions: totalFuncs,
      languageDistribution: langDist,
      functionTypeDistribution: funcTypeDist,
      topFiles: [...analysisResults].sort((a, b) => b.functionCount - a.functionCount).slice(0, 5)
    };
  }, [analysisResults]);

  const handleGenerateIdeas = async () => {
    if (!summary) return;
    setGenerating(true);
    setError(null);
    try {
      const ideas = await generateAppIdeas(summary);
      setAppIdeas(ideas);
    } catch (err) {
      setError("AI Generation failed. Check your Gemini API status.");
      console.error(err);
    } finally {
      setGenerating(false);
    }
  };

  const chartDataLanguages = useMemo(() => {
    if (!summary) return [];
    return Object.entries(summary.languageDistribution).map(([name, value]) => ({ name, value }));
  }, [summary]);

  const chartDataFunctions = useMemo(() => {
    if (!summary) return [];
    return Object.entries(summary.functionTypeDistribution).map(([name, value]) => ({ name, value }));
  }, [summary]);

  return (
    <div className="min-h-screen bg-slate-950 text-slate-200">
      {/* Header */}
      <header className="border-b border-slate-800 bg-slate-900/50 backdrop-blur-md sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-indigo-600 rounded-lg">
              <Layers className="w-6 h-6 text-white" />
            </div>
            <div>
              <h1 className="font-bold text-xl tracking-tight text-white">Snippet Architect AI</h1>
              <p className="text-xs text-slate-400">Code Analysis & App Brainstorming</p>
            </div>
          </div>

          <div className="flex items-center gap-4">
            <button 
              onClick={() => fileInputRef.current?.click()}
              className="flex items-center gap-2 px-4 py-2 bg-slate-800 hover:bg-slate-700 transition-colors rounded-lg text-sm font-medium border border-slate-700"
            >
              <FolderOpen className="w-4 h-4" />
              Upload Folder
            </button>
            <input 
              type="file" 
              ref={fileInputRef} 
              className="hidden" 
              multiple 
              // @ts-ignore
              webkitdirectory="" 
              directory="" 
              onChange={handleFileUpload} 
            />
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-8 space-y-8">
        {error && (
          <div className="p-4 bg-red-500/10 border border-red-500/20 rounded-xl flex items-center gap-3 text-red-400">
            <AlertCircle className="w-5 h-5" />
            <p>{error}</p>
          </div>
        )}

        {/* Empty State */}
        {!summary && !analyzing && (
          <div className="flex flex-col items-center justify-center py-24 text-center space-y-6">
            <div className="w-20 h-20 bg-slate-900 rounded-3xl flex items-center justify-center border border-slate-800">
              <FileCode className="w-10 h-10 text-indigo-400" />
            </div>
            <div className="max-w-md">
              <h2 className="text-2xl font-bold text-white mb-2">Ready to architect your snippets?</h2>
              <p className="text-slate-400">Upload a folder of source code files (JS, TS, Python, Java, etc.) to analyze function patterns and generate Android app ideas.</p>
            </div>
            <button 
              onClick={() => fileInputRef.current?.click()}
              className="px-8 py-3 bg-indigo-600 hover:bg-indigo-500 transition-colors rounded-xl font-semibold shadow-lg shadow-indigo-500/20"
            >
              Select Project Folder
            </button>
          </div>
        )}

        {/* Loading State */}
        {analyzing && (
          <div className="flex flex-col items-center justify-center py-24 space-y-4">
            <Loader2 className="w-12 h-12 text-indigo-500 animate-spin" />
            <p className="text-slate-400 font-medium">Parsing code snippets and mapping functions...</p>
          </div>
        )}

        {/* Analysis Dashboard */}
        {summary && !analyzing && (
          <div className="space-y-8 animate-in fade-in duration-500">
            {/* Stats Overview */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
              {[
                { label: 'Total Files', value: summary.totalFiles, icon: FileCode, color: 'text-blue-400' },
                { label: 'Functions Found', value: summary.totalFunctions, icon: Cpu, color: 'text-purple-400' },
                { label: 'Unique Languages', value: Object.keys(summary.languageDistribution).length, icon: Code2, color: 'text-emerald-400' },
                { label: 'UI Components', value: summary.functionTypeDistribution['UI'] || 0, icon: Layout, color: 'text-pink-400' },
              ].map((stat, i) => (
                <div key={i} className="bg-slate-900 border border-slate-800 p-6 rounded-2xl">
                  <div className="flex items-center justify-between mb-4">
                    <stat.icon className={`w-6 h-6 ${stat.color}`} />
                  </div>
                  <h3 className="text-3xl font-bold text-white">{stat.value}</h3>
                  <p className="text-slate-500 text-sm font-medium">{stat.label}</p>
                </div>
              ))}
            </div>

            {/* Charts Section */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              <div className="bg-slate-900 border border-slate-800 p-6 rounded-2xl">
                <div className="flex items-center gap-2 mb-6">
                  <BarChart3 className="w-5 h-5 text-indigo-400" />
                  <h3 className="font-bold text-lg">Language Distribution</h3>
                </div>
                <div className="h-[300px]">
                  <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                      <Pie
                        data={chartDataLanguages}
                        cx="50%"
                        cy="50%"
                        innerRadius={60}
                        outerRadius={80}
                        paddingAngle={5}
                        dataKey="value"
                      >
                        {chartDataLanguages.map((entry, index) => (
                          <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                        ))}
                      </Pie>
                      <Tooltip 
                        contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #1e293b' }}
                        itemStyle={{ color: '#fff' }}
                      />
                      <Legend />
                    </PieChart>
                  </ResponsiveContainer>
                </div>
              </div>

              <div className="bg-slate-900 border border-slate-800 p-6 rounded-2xl">
                <div className="flex items-center gap-2 mb-6">
                  <Settings2 className="w-5 h-5 text-purple-400" />
                  <h3 className="font-bold text-lg">Functional Breakdown</h3>
                </div>
                <div className="h-[300px]">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={chartDataFunctions}>
                      <XAxis dataKey="name" stroke="#94a3b8" fontSize={12} />
                      <YAxis stroke="#94a3b8" fontSize={12} />
                      <Tooltip 
                        contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #1e293b' }}
                        cursor={{ fill: 'rgba(255,255,255,0.05)' }}
                      />
                      <Bar dataKey="value" fill="#6366f1" radius={[4, 4, 0, 0]} />
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </div>
            </div>

            {/* Top Files List */}
            <div className="bg-slate-900 border border-slate-800 rounded-2xl overflow-hidden">
              <div className="p-6 border-b border-slate-800 flex items-center justify-between">
                <h3 className="font-bold text-lg flex items-center gap-2">
                  <FileCode className="w-5 h-5 text-blue-400" />
                  Most Dense Snippets
                </h3>
              </div>
              <div className="divide-y divide-slate-800">
                {summary.topFiles.map((file, i) => (
                  <div key={i} className="p-4 hover:bg-slate-800/30 transition-colors flex items-center justify-between">
                    <div className="flex items-center gap-4">
                      <div className="w-10 h-10 rounded-lg bg-slate-800 flex items-center justify-center text-indigo-400 font-bold">
                        {file.language.substring(0, 2).toUpperCase()}
                      </div>
                      <div>
                        <p className="font-medium text-slate-200">{file.fileName}</p>
                        <p className="text-xs text-slate-500 uppercase tracking-wider">{file.language}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-8 text-sm">
                      <div className="text-center">
                        <p className="text-slate-500 text-xs">LOC</p>
                        <p className="font-bold text-slate-300">{file.linesOfCode}</p>
                      </div>
                      <div className="text-center">
                        <p className="text-slate-500 text-xs">Functions</p>
                        <p className="font-bold text-indigo-400">{file.functionCount}</p>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* AI Generator CTA */}
            <div className="p-8 bg-gradient-to-r from-indigo-900/40 to-purple-900/40 border border-indigo-500/20 rounded-3xl flex flex-col md:flex-row items-center gap-8 text-center md:text-left">
              <div className="p-4 bg-indigo-500/20 rounded-2xl">
                <Lightbulb className="w-12 h-12 text-indigo-400" />
              </div>
              <div className="flex-1">
                <h3 className="text-2xl font-bold text-white mb-2">Discover what you can build</h3>
                <p className="text-indigo-200/70">Our AI can architect custom Android application concepts based on the reusable functions found in your code.</p>
              </div>
              <button 
                onClick={handleGenerateIdeas}
                disabled={generating}
                className="px-8 py-4 bg-indigo-600 hover:bg-indigo-500 disabled:opacity-50 transition-all rounded-xl font-bold flex items-center gap-2 shadow-xl shadow-indigo-500/30 active:scale-95"
              >
                {generating ? <Loader2 className="w-5 h-5 animate-spin" /> : <Lightbulb className="w-5 h-5" />}
                {generating ? 'Architecting...' : 'Generate App Ideas'}
              </button>
            </div>

            {/* AI Results */}
            {appIdeas.length > 0 && (
              <div className="space-y-6 pt-8 animate-in slide-in-from-bottom-8 duration-700">
                <div className="flex items-center gap-3">
                  <div className="h-px flex-1 bg-slate-800"></div>
                  <h2 className="text-2xl font-bold text-white px-4">AI Suggested Blueprints</h2>
                  <div className="h-px flex-1 bg-slate-800"></div>
