                      </div>
                      <h3 className="text-2xl font-bold text-white mb-4">{idea.title}</h3>
                      <p className="text-slate-400 mb-6 line-clamp-3 leading-relaxed">{idea.description}</p>

                      <div className="space-y-4">
                        <div>
                          <p className="text-xs font-bold text-slate-500 uppercase mb-2 tracking-wider">Core Features</p>
                          <div className="flex flex-wrap gap-2">
                            {idea.keyFeatures.map((f, j) => (
                              <span key={j} className="text-xs px-2 py-1 bg-slate-800 text-slate-300 rounded-md border border-slate-700">
                                {f}
                              </span>
                            ))}
