                        </div>
                        <div>
                          <p className="text-xs font-bold text-slate-500 uppercase mb-2 tracking-wider">Suggested Stack</p>
                          <div className="flex flex-wrap gap-2">
                            {idea.techStack.map((s, j) => (
                              <span key={j} className="text-xs px-2 py-1 bg-purple-500/10 text-purple-400 rounded-md border border-purple-500/20">
                                {s}
                              </span>
                            ))}
                          </div>
                        </div>
                      </div>

                      <button className="mt-8 w-full py-3 bg-slate-800 hover:bg-slate-700 text-white rounded-xl font-semibold flex items-center justify-center gap-2 group transition-colors">
                        View Full Blueprint
                        <ChevronRight className="w-4 h-4 group-hover:translate-x-1 transition-transform" />
                      </button>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        )}
      </main>

      <footer className="border-t border-slate-800 py-12 mt-20">
        <div className="max-w-7xl mx-auto px-4 flex flex-col md:flex-row items-center justify-between gap-6 text-slate-500 text-sm">
          <p>© 2024 Snippet Architect AI. All analysis performed locally.</p>
          <div className="flex items-center gap-6">
            <a href="#" className="hover:text-indigo-400">Documentation</a>
            <a href="#" className="hover:text-indigo-400">Privacy</a>
            <a href="#" className="hover:text-indigo-400">GitHub</a>
          </div>
        </div>
      </footer>
    </div>
  );
}

import React, { useState, useRef, useMemo } from 'react';
import { 
  FileCode, 
  FolderOpen, 
  BarChart3, 
  Lightbulb, 
  Cpu, 
  Layout, 
  Code2, 
  AlertCircle,
  Loader2,
  ChevronRight,
  Settings2,
  Layers,
  X,
  Code
} from 'lucide-react';
import { 
  PieChart, 
  Pie, 
  Cell, 
  ResponsiveContainer, 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  Tooltip, 
  Legend 
} from 'recharts';
import { CodeFile, FileAnalysisResult, AnalysisSummary, AppIdea, FunctionAnalysis } from './types';
import { analyzeFile } from './services/codeParser';
import { generateAppIdeas } from './services/geminiService';

const COLORS = ['#6366f1', '#a855f7', '#ec4899', '#f43f5e', '#8b5cf6', '#06b6d4'];

const TYPE_COLORS: Record<FunctionAnalysis['type'], string> = {
  UI: 'text-pink-400 bg-pink-400/10 border-pink-400/20',
  Logic: 'text-indigo-400 bg-indigo-400/10 border-indigo-400/20',
  API: 'text-cyan-400 bg-cyan-400/10 border-cyan-400/20',
  Database: 'text-emerald-400 bg-emerald-400/10 border-emerald-400/20',
  Utility: 'text-slate-400 bg-slate-400/10 border-slate-400/20',
  Unknown: 'text-slate-500 bg-slate-500/10 border-slate-500/20',
};

export default function App() {
  const [files, setFiles] = useState<CodeFile[]>([]);
  const [analyzing, setAnalyzing] = useState(false);
  const [generating, setGenerating] = useState(false);
  const [analysisResults, setAnalysisResults] = useState<FileAnalysisResult[]>([]);
  const [appIdeas, setAppIdeas] = useState<AppIdea[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [selectedFileIndex, setSelectedFileIndex] = useState<number | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const fileList = e.target.files;
    if (!fileList || fileList.length === 0) return;

    setAnalyzing(true);
    setError(null);
    setAnalysisResults([]);
    setAppIdeas([]);
    setSelectedFileIndex(null);

    const newFiles: CodeFile[] = [];

    try {
      for (let i = 0; i < fileList.length; i++) {
        const file = fileList[i];
        const content = await file.text();
        newFiles.push({
          name: file.name,
          path: (file as any).webkitRelativePath || file.name,
          content,
          language: file.name.split('.').pop() || 'txt',
          size: file.size
        });
      }

      setFiles(newFiles);
      const results = newFiles.map(analyzeFile);
      setAnalysisResults(results);
    } catch (err) {
      setError("Failed to read files. Please try again.");
      console.error(err);
    } finally {
      setAnalyzing(false);
    }
  };

  const summary = useMemo<AnalysisSummary | null>(() => {
    if (analysisResults.length === 0) return null;

    const langDist: Record<string, number> = {};
    const funcTypeDist: Record<string, number> = {};
    let totalFuncs = 0;

    analysisResults.forEach(res => {
      langDist[res.language] = (langDist[res.language] || 0) + 1;
      totalFuncs += res.functionCount;
      res.functions.forEach(f => {
        funcTypeDist[f.type] = (funcTypeDist[f.type] || 0) + 1;
      });
    });

    return {
      totalFiles: analysisResults.length,
      totalFunctions: totalFuncs,
      languageDistribution: langDist,
      functionTypeDistribution: funcTypeDist,
      topFiles: [...analysisResults].sort((a, b) => b.functionCount - a.functionCount).slice(0, 10)
    };
  }, [analysisResults]);

  const handleGenerateIdeas = async () => {
    if (!summary) return;
    setGenerating(true);
    setError(null);
    try {
      const ideas = await generateAppIdeas(summary);
      setAppIdeas(ideas);
    } catch (err) {
      setError("AI Generation failed. Check your Gemini API status.");
      console.error(err);
    } finally {
      setGenerating(false);
    }
  };

  const chartDataLanguages = useMemo(() => {
    if (!summary) return [];
    return Object.entries(summary.languageDistribution).map(([name, value]) => ({ name, value }));
  }, [summary]);

  const chartDataFunctions = useMemo(() => {
    if (!summary) return [];
    return Object.entries(summary.functionTypeDistribution).map(([name, value]) => ({ name, value }));
  }, [summary]);

  const selectedFile = selectedFileIndex !== null ? summary?.topFiles[selectedFileIndex] : null;

  return (
    <div className="min-h-screen bg-slate-950 text-slate-200">
      {/* Header */}
      <header className="border-b border-slate-800 bg-slate-900/50 backdrop-blur-md sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3 cursor-pointer" onClick={() => window.location.reload()}>
            <div className="p-2 bg-indigo-600 rounded-lg">
              <Layers className="w-6 h-6 text-white" />
            </div>
            <div>
              <h1 className="font-bold text-xl tracking-tight text-white">Snippet Architect AI</h1>
              <p className="text-xs text-slate-400">Code Analysis & App Brainstorming</p>
            </div>
          </div>

          <div className="flex items-center gap-4">
            <button 
              onClick={() => fileInputRef.current?.click()}
              className="flex items-center gap-2 px-4 py-2 bg-slate-800 hover:bg-slate-700 transition-colors rounded-lg text-sm font-medium border border-slate-700"
            >
              <FolderOpen className="w-4 h-4" />
              Upload Folder
            </button>
            <input 
              type="file" 
              ref={fileInputRef} 
              className="hidden" 
              multiple 
              // @ts-ignore
              webkitdirectory="" 
              directory="" 
              onChange={handleFileUpload} 
            />
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-8 space-y-8">
        {error && (
          <div className="p-4 bg-red-500/10 border border-red-500/20 rounded-xl flex items-center gap-3 text-red-400">
            <AlertCircle className="w-5 h-5" />
