import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisSummary, OverseerReport } from "../types";

export async function runOverseerAnalysis(summary: AnalysisSummary, directive: string): Promise<OverseerReport> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    ACT AS THE INTELLIGENCE OVERSEER.
    Project Context:
    - Files: ${summary.totalFiles}
    - Functions: ${summary.totalFunctions}
    - Tech: ${JSON.stringify(summary.languageDistribution)}

    Current Directive: ${directive}

    Analyze this snippet collection for high-level architectural integrity and automation potential.
    Evaluate the "Constructibility Score" (0-100) - how ready are these pieces to be automatically assembled into a product?

    Provide your assessment in JSON format:
    - status: "OPTIMAL", "WARNING", or "CRITICAL"
    - constructibilityScore: number (0-100)
    - intelligenceInsights: array of strings (architectural advice)
    - suggestedAutomations: array of strings (CI/CD, code gen, or automated logic suggestions)
  `;

  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          status: { type: Type.STRING },
          constructibilityScore: { type: Type.NUMBER },
          intelligenceInsights: { 
            type: Type.ARRAY,
            items: { type: Type.STRING }
          },
          suggestedAutomations: {
            type: Type.ARRAY,
            items: { type: Type.STRING }
          }
        },
        required: ["status", "constructibilityScore", "intelligenceInsights", "suggestedAutomations"]
      }
    }
  });

  try {
    return JSON.parse(response.text);
  } catch (error) {
    console.error("Overseer analysis failed", error);
    return {
      status: 'WARNING',
      constructibilityScore: 50,
      intelligenceInsights: ["Parsing error in overseer intelligence."],
      suggestedAutomations: ["Manual audit required."]
    };
  }
}

import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisSummary, AppIdea } from "../types";

export async function generateAppIdeas(summary: AnalysisSummary, directive: string = ""): Promise<AppIdea[]> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    I have analyzed a codebase with the following statistics:
    - Total Files: ${summary.totalFiles}
    - Total Functions Found: ${summary.totalFunctions}
    - Languages Used: ${JSON.stringify(summary.languageDistribution)}
    - Function Types Breakdown: ${JSON.stringify(summary.functionTypeDistribution)}

    OVERSEER DIRECTIVE: ${directive}

    Based on these code snippets, suggest 4-5 highly relevant Android application ideas.
    Focus on "User-Driven Automation" and "Lucrative Intelligence" - how can these apps create value automatically?

    For each idea, provide:
    1. A catchy title.
    2. A detailed description.
    3. A relevance score (0-100).
    4. Key features.
    5. Recommended tech stack.
    6. A specific "Monetization Strategy" (how it becomes lucrative).
    7. "Automation Potential" (how the app can run or improve itself using AI).
  `;

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            description: { type: Type.STRING },
            relevanceScore: { type: Type.NUMBER },
            keyFeatures: { 
              type: Type.ARRAY,
              items: { type: Type.STRING }
            },
            techStack: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            },
            monetizationStrategy: { type: Type.STRING },
            automationPotential: { type: Type.STRING }
          },
          required: ["title", "description", "relevanceScore", "keyFeatures", "techStack", "monetizationStrategy", "automationPotential"]
        }
      }
    }
  });

  try {
    return JSON.parse(response.text);
  } catch (error) {
    console.error("Failed to parse Gemini response", error);
    return [];
  }
}

