import { generateAppIdeas } from './services/geminiService';
import { runOverseerAnalysis } from './services/overseerService';

const COLORS = ['#6366f1', '#a855f7', '#ec4899', '#f43f5e', '#8b5cf6', '#06b6d4'];

const TYPE_COLORS: Record<FunctionAnalysis['type'], string> = {
  UI: 'text-pink-400 bg-pink-400/10 border-pink-400/20',
  Logic: 'text-indigo-400 bg-indigo-400/10 border-indigo-400/20',
  API: 'text-cyan-400 bg-cyan-400/10 border-cyan-400/20',
  Database: 'text-emerald-400 bg-emerald-400/10 border-emerald-400/20',
  Utility: 'text-slate-400 bg-slate-400/10 border-slate-400/20',
  Unknown: 'text-slate-500 bg-slate-500/10 border-slate-500/20',
};

const DIRECTIVES: OverseerDirective[] = [
  { id: 'revenue', label: 'Lucrative Growth', prompt: 'Maximize monetization and recurring revenue automation.', icon: 'DollarSign' },
  { id: 'security', label: 'Security Fortress', prompt: 'Prioritize data integrity and hardened security snippets.', icon: 'ShieldAlert' },
  { id: 'efficiency', label: 'Ultra Efficiency', prompt: 'Focus on code modularity and high-speed execution logic.', icon: 'Zap' },
  { id: 'ai', label: 'AI Intelligence', prompt: 'Embed predictive AI and self-learning loops into the construction.', icon: 'Bot' },
];

export default function App() {
  const [files, setFiles] = useState<CodeFile[]>([]);
  const [analyzing, setAnalyzing] = useState(false);
  const [generating, setGenerating] = useState(false);
  const [overseerLoading, setOverseerLoading] = useState(false);
  const [analysisResults, setAnalysisResults] = useState<FileAnalysisResult[]>([]);
  const [appIdeas, setAppIdeas] = useState<AppIdea[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [selectedFileIndex, setSelectedFileIndex] = useState<number | null>(null);
  const [activeDirective, setActiveDirective] = useState(DIRECTIVES[0]);
  const [overseerReport, setOverseerReport] = useState<OverseerReport | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const fileList = e.target.files;
    if (!fileList || fileList.length === 0) return;

    setAnalyzing(true);
    setError(null);
    setAnalysisResults([]);
    setAppIdeas([]);
    setOverseerReport(null);
    setSelectedFileIndex(null);

    const newFiles: CodeFile[] = [];

    try {
      for (let i = 0; i < fileList.length; i++) {
        const file = fileList[i];
        const content = await file.text();
        newFiles.push({
          name: file.name,
          path: (file as any).webkitRelativePath || file.name,
          content,
          language: file.name.split('.').pop() || 'txt',
          size: file.size
        });
      }

      setFiles(newFiles);
      const results = newFiles.map(analyzeFile);
      setAnalysisResults(results);
    } catch (err) {
      setError("Failed to read files. Please try again.");
      console.error(err);
    } finally {
      setAnalyzing(false);
    }
  };

  const summary = useMemo<AnalysisSummary | null>(() => {
    if (analysisResults.length === 0) return null;

    const langDist: Record<string, number> = {};
    const funcTypeDist: Record<string, number> = {};
    let totalFuncs = 0;

    analysisResults.forEach(res => {
      langDist[res.language] = (langDist[res.language] || 0) + 1;
      totalFuncs += res.functionCount;
      res.functions.forEach(f => {
        funcTypeDist[f.type] = (funcTypeDist[f.type] || 0) + 1;
      });
    });

    return {
      totalFiles: analysisResults.length,
      totalFunctions: totalFuncs,
      languageDistribution: langDist,
      functionTypeDistribution: funcTypeDist,
      topFiles: [...analysisResults].sort((a, b) => b.functionCount - a.functionCount).slice(0, 10),
      overseerReport: overseerReport || undefined
    };
  }, [analysisResults, overseerReport]);

  const handleOverseerActivation = async () => {
    if (!summary) return;
    setOverseerLoading(true);
    try {
      const report = await runOverseerAnalysis(summary, activeDirective.prompt);
      setOverseerReport(report);
    } catch (err) {
      setError("Overseer intelligence loop failed.");
    } finally {
      setOverseerLoading(false);
    }
  };

  const handleGenerateIdeas = async () => {
    if (!summary) return;
    setGenerating(true);
    setError(null);
    try {
      const ideas = await generateAppIdeas(summary, activeDirective.prompt);
      setAppIdeas(ideas);
    } catch (err) {
      setError("AI Generation failed. Check your Gemini API status.");
      console.error(err);
    } finally {
      setGenerating(false);
    }
  };

  const chartDataLanguages = useMemo(() => {
    if (!summary) return [];
    return Object.entries(summary.languageDistribution).map(([name, value]) => ({ name, value }));
  }, [summary]);

  const chartDataFunctions = useMemo(() => {
    if (!summary) return [];
    return Object.entries(summary.functionTypeDistribution).map(([name, value]) => ({ name, value }));
  }, [summary]);

  const selectedFile = selectedFileIndex !== null ? summary?.topFiles[selectedFileIndex] : null;

  return (
    <div className="min-h-screen bg-slate-950 text-slate-200">
      {/* Header */}
      <header className="border-b border-slate-800 bg-slate-900/80 backdrop-blur-xl sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3 cursor-pointer group" onClick={() => window.location.reload()}>
            <div className="p-2 bg-indigo-600 rounded-lg group-hover:rotate-12 transition-transform">
              <Bot className="w-6 h-6 text-white" />
            </div>
            <div>
              <h1 className="font-black text-xl tracking-tighter text-white">INTELLIGENCE OVERSEER</h1>
              <p className="text-[10px] text-indigo-400 font-bold uppercase tracking-[0.2em]">Automated Construction Core</p>
            </div>
          </div>

          <div className="flex items-center gap-4">
            <button 
              onClick={() => fileInputRef.current?.click()}
              className="flex items-center gap-2 px-4 py-2 bg-slate-900 hover:bg-slate-800 transition-colors rounded-lg text-sm font-bold border border-indigo-500/20 text-indigo-100 shadow-lg shadow-indigo-500/10"
            >
              <FolderOpen className="w-4 h-4" />
              Ingest Snippets
            </button>
            <input 
              type="file" 
              ref={fileInputRef} 
              className="hidden" 
              multiple 
              // @ts-ignore
              webkitdirectory="" 
              directory="" 
              onChange={handleFileUpload} 
            />
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-8 space-y-8">
        {error && (
          <div className="p-4 bg-red-500/10 border border-red-500/20 rounded-xl flex items-center gap-3 text-red-400 animate-pulse">
            <ShieldAlert className="w-5 h-5" />
            <p className="font-bold">{error}</p>
          </div>
        )}

        {/* Empty State */}
        {!summary && !analyzing && (
          <div className="flex flex-col items-center justify-center py-24 text-center space-y-8">
            <div className="relative">
               <div className="absolute inset-0 bg-indigo-500/20 blur-3xl rounded-full animate-pulse"></div>
               <div className="relative w-24 h-24 bg-slate-900 rounded-[2rem] flex items-center justify-center border-2 border-slate-800 shadow-2xl">
                 <Terminal className="w-12 h-12 text-indigo-400" />
               </div>
            </div>
            <div className="max-w-xl">
              <h2 className="text-4xl font-black text-white mb-4 tracking-tighter">ESTABLISH CONTROL.</h2>
              <p className="text-slate-400 text-lg leading-relaxed">The Intelligence Overseer transforms raw code snippets into lucrative automated structures. Upload your repository to begin the synthesis.</p>
            </div>
            <button 
              onClick={() => fileInputRef.current?.click()}
              className="px-10 py-4 bg-indigo-600 hover:bg-indigo-500 transition-all rounded-2xl font-black text-lg shadow-2xl shadow-indigo-600/30 hover:-translate-y-1 active:scale-95 border-b-4 border-indigo-800"
            >
              INITIALIZE UPLOAD
            </button>
          </div>
        )}

        {/* Analysis Dashboard */}
        {summary && !analyzing && (
          <div className="space-y-8 animate-in fade-in duration-500">

            {/* Overseer Command Panel */}
            <section className="bg-slate-900/50 border border-indigo-500/30 rounded-[2.5rem] p-8 shadow-2xl relative overflow-hidden group">
              <div className="absolute top-0 right-0 p-10 opacity-5">
                <Activity className="w-64 h-64 text-indigo-400" />
              </div>

              <div className="flex flex-col lg:flex-row gap-12 relative z-10">
                <div className="flex-1 space-y-6">
                  <div className="flex items-center gap-3">
                    <div className="p-2 bg-indigo-600/20 rounded-lg text-indigo-400">
                      <Zap className="w-6 h-6" />
                    </div>
                    <h2 className="text-2xl font-black text-white tracking-tight">OVERSEER DIRECTIVES</h2>
                  </div>

                  <div className="grid grid-cols-2 gap-4">
                    {DIRECTIVES.map((d) => (
                      <button
                        key={d.id}
                        onClick={() => setActiveDirective(d)}
                        className={`p-4 rounded-2xl border-2 text-left transition-all ${activeDirective.id === d.id ? 'border-indigo-500 bg-indigo-500/10 shadow-lg' : 'border-slate-800 hover:border-slate-700 bg-slate-900/50'}`}
                      >
                        <p className={`font-black uppercase text-xs tracking-widest mb-1 ${activeDirective.id === d.id ? 'text-indigo-400' : 'text-slate-500'}`}>
                          {d.label}
                        </p>
                        <p className="text-sm text-slate-400 line-clamp-1">{d.prompt}</p>
                      </button>
                    ))}
                  </div>

                  <button
                    onClick={handleOverseerActivation}
                    disabled={overseerLoading}
                    className="w-full py-4 bg-white text-slate-950 rounded-2xl font-black text-lg hover:bg-indigo-100 transition-all flex items-center justify-center gap-3 active:scale-95 shadow-xl disabled:opacity-50"
                  >
                    {overseerLoading ? <Loader2 className="w-6 h-6 animate-spin" /> : <Activity className="w-6 h-6" />}
                    {overseerLoading ? 'RUNNING INTELLIGENCE LOOP...' : 'ACTIVATE INTELLIGENCE OVERSEER'}
                  </button>
                </div>

                <div className="flex-1 bg-slate-950/50 rounded-3xl border border-slate-800 p-8">
                  {overseerReport ? (
                    <div className="space-y-6 animate-in zoom-in-95 duration-300">
                      <div className="flex items-center justify-between">
                         <span className={`px-4 py-1 rounded-full text-xs font-black border ${overseerReport.status === 'OPTIMAL' ? 'bg-emerald-500/10 border-emerald-500/50 text-emerald-400' : 'bg-amber-500/10 border-amber-500/50 text-amber-400'}`}>
                           STATUS: {overseerReport.status}
                         </span>
                         <div className="text-right">
                           <p className="text-[10px] text-slate-500 font-bold uppercase">Constructibility</p>
                           <p className="text-2xl font-black text-white">{overseerReport.constructibilityScore}%</p>
                         </div>
                      </div>

                      <div>
                        <h4 className="text-xs font-black text-indigo-400 uppercase tracking-widest mb-3">Intelligence Insights</h4>
                        <ul className="space-y-2">
                          {overseerReport.intelligenceInsights.map((insight, i) => (
                            <li key={i} className="flex gap-2 text-sm text-slate-300">
                              <span className="text-indigo-500 mt-1">▹</span>
                              {insight}
                            </li>
                          ))}
                        </ul>
                      </div>

                      <div>
                        <h4 className="text-xs font-black text-pink-400 uppercase tracking-widest mb-3">Suggested Automations</h4>
                        <div className="flex flex-wrap gap-2">
                          {overseerReport.suggestedAutomations.map((a, i) => (
                            <span key={i} className="px-3 py-1 bg-pink-500/10 border border-pink-500/20 text-pink-400 text-[10px] font-bold rounded-lg uppercase">
                              {a}
                            </span>
                          ))}
                        </div>
                      </div>
                    </div>
                  ) : (
                    <div className="h-full flex flex-col items-center justify-center text-center py-12">
                      <Bot className="w-16 h-16 text-slate-800 mb-4" />
                      <p className="text-slate-500 font-bold">Overseer Idle.<br/>Awaiting synthesis directives.</p>
                    </div>
                  )}
                </div>
              </div>
            </section>

            {/* Stats Overview */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
              {[
                { label: 'Ingested Files', value: summary.totalFiles, icon: FileCode, color: 'text-blue-400' },
                { label: 'Total Functions', value: summary.totalFunctions, icon: Cpu, color: 'text-purple-400' },
                { label: 'Automation Hooks', value: summary.functionTypeDistribution['Logic'] || 0, icon: Zap, color: 'text-emerald-400' },
                { label: 'UI Blueprints', value: summary.functionTypeDistribution['UI'] || 0, icon: Layout, color: 'text-pink-400' },
              ].map((stat, i) => (
                <div key={i} className="bg-slate-900 border border-slate-800 p-6 rounded-[2rem] hover:border-slate-700 transition-all shadow-xl">
                  <div className="flex items-center justify-between mb-4">
                    <stat.icon className={`w-8 h-8 ${stat.color}`} />
                  </div>
                  <h3 className="text-4xl font-black text-white tracking-tighter">{stat.value}</h3>
                  <p className="text-slate-500 text-xs font-bold uppercase tracking-widest">{stat.label}</p>
                </div>
              ))}
            </div>

            {/* Ingested Content Explorer */}
            <div className="bg-slate-900 border border-slate-800 rounded-[2rem] overflow-hidden shadow-2xl">
              <div className="p-8 border-b border-slate-800 flex items-center justify-between bg-slate-900/50">
                <h3 className="font-black text-xl flex items-center gap-3 text-white tracking-tight uppercase">
                  <FileCode className="w-6 h-6 text-blue-400" />
                  Synthesis Source Matrix
                </h3>
              </div>
              <div className="divide-y divide-slate-800 max-h-[400px] overflow-y-auto">
                {summary.topFiles.map((file, i) => (
                  <div 
                    key={i} 
                    onClick={() => setSelectedFileIndex(i)}
                    className="p-6 hover:bg-slate-800/50 transition-all cursor-pointer flex items-center justify-between group"
                  >
                    <div className="flex items-center gap-6">
                      <div className="w-12 h-12 rounded-2xl bg-slate-800 border-2 border-slate-700 flex items-center justify-center text-indigo-400 font-black transition-transform group-hover:scale-110 group-hover:rotate-6">
                        {file.language.substring(0, 2).toUpperCase()}
                      </div>
                      <div>
                        <p className="text-lg font-black text-slate-200 group-hover:text-indigo-400 transition-colors tracking-tight">{file.fileName}</p>
                        <p className="text-[10px] text-slate-500 font-black uppercase tracking-[0.2em]">{file.language}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-10 text-sm">
                      <div className="text-right">
                        <p className="text-slate-500 text-[10px] font-black uppercase tracking-widest">Logic Density</p>
                        <p className="font-black text-indigo-400 text-2xl">{file.functionCount}</p>
                      </div>
                      <ChevronRight className="w-6 h-6 text-slate-700 group-hover:text-indigo-500 transition-colors" />
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Modal for Details */}
            {selectedFile && (
              <div className="fixed inset-0 z-[60] flex items-center justify-center p-6 bg-slate-950/90 backdrop-blur-md animate-in fade-in duration-300">
                <div className="bg-slate-900 border border-indigo-500/20 w-full max-w-5xl max-h-[90vh] rounded-[3rem] overflow-hidden flex flex-col shadow-2xl ring-1 ring-white/10">
                  <div className="p-8 border-b border-slate-800 flex items-center justify-between bg-slate-900/80">
                    <div className="flex items-center gap-6">
                      <div className="p-4 bg-indigo-500/20 rounded-[1.5rem] text-indigo-400">
                        <Code className="w-8 h-8" />
                      </div>
                      <div>
                        <h3 className="text-3xl font-black text-white tracking-tighter">{selectedFile.fileName}</h3>
                        <p className="text-xs text-slate-500 font-black uppercase tracking-[0.3em]">{selectedFile.language} • {selectedFile.linesOfCode} LOC</p>
                      </div>
                    </div>
                    <button 
                      onClick={() => setSelectedFileIndex(null)}
                      className="p-3 hover:bg-slate-800 rounded-full transition-colors text-slate-400 hover:text-white"
                    >
                      <X className="w-8 h-8" />
                    </button>
                  </div>

                  <div className="flex-1 overflow-y-auto p-8 space-y-8 bg-slate-950/20">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                      {selectedFile.functions.map((fn, idx) => (
                        <div key={idx} className="bg-slate-900 border border-slate-800 p-6 rounded-[2rem] group transition-all hover:border-indigo-500/30">
                          <div className="flex items-center justify-between mb-4">
                            <h4 className="font-black text-indigo-300 text-xl tracking-tight">{fn.name}</h4>
                            <span className={`text-[10px] font-black uppercase px-3 py-1 rounded-full border ${TYPE_COLORS[fn.type]}`}>
                              {fn.type}
                            </span>
                          </div>
                          <div className="bg-slate-950 rounded-2xl p-4 border border-slate-800 overflow-x-auto max-h-[200px]">
                            <pre className="text-xs text-slate-500 font-mono leading-relaxed">
                              <code>{fn.snippet}</code>
                            </pre>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>

                  <div className="p-6 border-t border-slate-800 bg-slate-900/50 flex justify-end gap-4">
                    <button 
                      onClick={() => setSelectedFileIndex(null)}
                      className="px-8 py-3 bg-slate-800 hover:bg-slate-700 text-white rounded-2xl font-black transition-all active:scale-95 uppercase tracking-widest text-xs"
                    >
                      Close Matrix
                    </button>
                  </div>
                </div>
              </div>
            )}

            {/* App Generation Section */}
            <div className="p-12 bg-gradient-to-br from-indigo-600 to-purple-700 rounded-[3rem] flex flex-col items-center gap-10 text-center shadow-2xl relative overflow-hidden group">
              <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')] opacity-10"></div>
              <div className="relative z-10 flex flex-col items-center gap-6">
                <div className="p-6 bg-white/20 backdrop-blur-md rounded-[2rem] shadow-2xl border border-white/30 group-hover:rotate-12 transition-transform duration-500">
                  <Briefcase className="w-16 h-16 text-white" />
                </div>
                <div className="max-w-2xl">
                  <h3 className="text-5xl font-black text-white mb-4 tracking-tighter italic">LUCRATIVE BLUEPRINTS</h3>
                  <p className="text-indigo-100/80 text-xl font-medium">The Overseer is ready to project high-value application architectures designed for automated revenue and rapid construction.</p>
                </div>
                <button 
                  onClick={handleGenerateIdeas}
                  disabled={generating}
                  className="px-12 py-6 bg-white text-indigo-600 hover:bg-indigo-50 disabled:opacity-50 transition-all rounded-[2rem] font-black text-2xl flex items-center gap-4 shadow-2xl active:scale-95 min-w-[320px] justify-center"
                >
                  {generating ? <Loader2 className="w-8 h-8 animate-spin" /> : <DollarSign className="w-8 h-8" />}
                  {generating ? 'SYNTHESIZING...' : 'PROJECT BLUEPRINTS'}
                </button>
              </div>
            </div>

            {/* Generated App Cards */}
            {appIdeas.length > 0 && (
              <div className="space-y-12 py-12">
                <div className="flex items-center gap-6">
                  <div className="h-[2px] flex-1 bg-gradient-to-r from-transparent to-slate-800"></div>
                  <h2 className="text-3xl font-black text-white px-6 uppercase tracking-tighter italic">Synthesis Output</h2>
                  <div className="h-[2px] flex-1 bg-gradient-to-l from-transparent to-slate-800"></div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  {appIdeas.map((idea, i) => (
                    <div key={i} className="bg-slate-900 border-2 border-slate-800 p-10 rounded-[3rem] hover:border-indigo-500/50 transition-all group relative overflow-hidden flex flex-col h-full shadow-2xl">
                      <div className="absolute top-0 right-0 p-8 opacity-5 group-hover:opacity-10 transition-opacity">
                        <Bot className="w-48 h-48 text-white" />
                      </div>

                      <div className="flex justify-between items-start mb-8 relative z-10">
                        <div className="px-5 py-2 bg-indigo-500/10 text-indigo-400 text-xs font-black rounded-full border border-indigo-500/20 uppercase tracking-[0.2em]">
                          RELEVANCE: {idea.relevanceScore}%
                        </div>
                        <div className="flex gap-2">
                           <div className="p-2 bg-emerald-500/10 text-emerald-400 rounded-lg">
                             <DollarSign className="w-5 h-5" />
                           </div>
                           <div className="p-2 bg-pink-500/10 text-pink-400 rounded-lg">
                             <Zap className="w-5 h-5" />
                           </div>
                        </div>
                      </div>

                      <h3 className="text-3xl font-black text-white mb-6 group-hover:text-indigo-400 transition-colors tracking-tighter">{idea.title}</h3>
                      <p className="text-slate-400 text-lg mb-8 flex-1 leading-relaxed font-medium">{idea.description}</p>

                      <div className="space-y-8 mb-10">
                        <div className="p-6 bg-emerald-500/5 rounded-[2rem] border border-emerald-500/10">
                          <p className="text-[10px] font-black text-emerald-500 uppercase mb-3 tracking-widest flex items-center gap-2">
                            <DollarSign className="w-3 h-3" />
                            Lucrative Strategy
                          </p>
                          <p className="text-sm text-slate-300 font-medium italic">"{idea.monetizationStrategy}"</p>
                        </div>

                        <div className="p-6 bg-indigo-500/5 rounded-[2rem] border border-indigo-500/10">
                          <p className="text-[10px] font-black text-indigo-400 uppercase mb-3 tracking-widest flex items-center gap-2">
                            <Bot className="w-3 h-3" />
                            Intelligence Overseer Potential
                          </p>
                          <p className="text-sm text-slate-300 font-medium italic">"{idea.automationPotential}"</p>
                        </div>

                        <div className="grid grid-cols-2 gap-4">
                           <div>
                             <p className="text-[9px] font-black text-slate-500 uppercase mb-2 tracking-widest">Automation Hooks</p>
                             <div className="flex flex-wrap gap-2">
                                {idea.keyFeatures.slice(0, 3).map((f, j) => (
                                  <span key={j} className="text-[9px] px-3 py-1 bg-slate-800 text-slate-400 rounded-lg border border-slate-700 font-bold uppercase">
                                    {f}
                                  </span>
                                ))}
                             </div>
                           </div>
                           <div>
                             <p className="text-[9px] font-black text-slate-500 uppercase mb-2 tracking-widest">Construction Stack</p>
                             <div className="flex flex-wrap gap-2">
                                {idea.techStack.slice(0, 2).map((s, j) => (
                                  <span key={j} className="text-[9px] px-3 py-1 bg-purple-500/10 text-purple-400 rounded-lg border border-purple-500/20 font-bold uppercase">
                                    {s}
                                  </span>
                                ))}
                             </div>
                           </div>
                        </div>
                      </div>

                      <button className="mt-auto w-full py-5 bg-indigo-600 hover:bg-indigo-500 text-white rounded-[2rem] font-black text-lg flex items-center justify-center gap-3 group transition-all active:scale-95 shadow-xl border-b-4 border-indigo-800">
                        INITIALIZE CONSTRUCTION
                        <ChevronRight className="w-6 h-6 group-hover:translate-x-2 transition-transform" />
                      </button>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        )}
      </main>

      <footer className="border-t border-slate-900 py-16 mt-20 bg-slate-950">
