import { GoogleGenAI, Type } from "@google/genai";
import { AppIdea } from "../types";

export async function constructAssetSource(idea: AppIdea): Promise<string> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    ACT AS THE MASTER ARCHITECT & CONSTRUCTION ENGINE.

    Synthesize a complete source code manifest for the following wealth asset:
    Title: ${idea.title}
    Description: ${idea.description}
    Tech Stack: ${idea.techStack.join(', ')}
    Monetization: ${idea.monetizationStrategy}

    Requirement: 
    Generate a high-level multi-platform source code blueprint. 
    Include the directory structure, core logic modules (incorporating the automation loops), and UI boilerplate code.
    Format the output as a structured text manifest that acts as the 'Source Code Pack' for this application.
    Focus on creating a 'Downloadable Blueprint' that a developer or automated CI/CD can immediately ingest to start the build.
  `;

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: prompt,
    config: {
      thinkingConfig: { thinkingBudget: 32768 },
    }
  });

  return response.text || "Synthesis failed to produce a valid manifest.";
}

