  const [appIdeas, setAppIdeas] = useState<AppIdea[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [selectedFileIndex, setSelectedFileIndex] = useState<number | null>(null);
  const [activeDirective, setActiveDirective] = useState(DIRECTIVES[0]);
  const [overseerReport, setOverseerReport] = useState<OverseerReport | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const fileList = e.target.files;
    if (!fileList || fileList.length === 0) return;

    setAnalyzing(true);
    setError(null);
    setAnalysisResults([]);
    setAppIdeas([]);
    setOverseerReport(null);
    setSelectedFileIndex(null);

    const newFiles: CodeFile[] = [];

    try {
      for (let i = 0; i < fileList.length; i++) {
        const file = fileList[i];
        const content = await file.text();
        newFiles.push({
          name: file.name,
          path: (file as any).webkitRelativePath || file.name,
          content,
          language: file.name.split('.').pop() || 'txt',
          size: file.size
        });
      }

      setFiles(newFiles);
      const results = newFiles.map(analyzeFile);
      setAnalysisResults(results);
    } catch (err) {
      setError("Failed to read files. Please try again.");
      console.error(err);
    } finally {
      setAnalyzing(false);
    }
  };

  const summary = useMemo<AnalysisSummary | null>(() => {
    if (analysisResults.length === 0) return null;

    const langDist: Record<string, number> = {};
    const funcTypeDist: Record<string, number> = {};
    let totalFuncs = 0;

    analysisResults.forEach(res => {
      langDist[res.language] = (langDist[res.language] || 0) + 1;
      totalFuncs += res.functionCount;
      res.functions.forEach(f => {
        funcTypeDist[f.type] = (funcTypeDist[f.type] || 0) + 1;
      });
    });

    return {
      totalFiles: analysisResults.length,
      totalFunctions: totalFuncs,
      languageDistribution: langDist,
      functionTypeDistribution: funcTypeDist,
      topFiles: [...analysisResults].sort((a, b) => b.functionCount - a.functionCount).slice(0, 10),
      overseerReport: overseerReport || undefined
    };
  }, [analysisResults, overseerReport]);

  const handleOverseerActivation = async () => {
    if (!summary) return;
    setOverseerLoading(true);
    try {
      const report = await runOverseerAnalysis(summary, activeDirective.prompt);
      setOverseerReport(report);
    } catch (err) {
      setError("Overseer intelligence failure.");
    } finally {
      setOverseerLoading(false);
    }
  };

  const handleGenerateIdeas = async () => {
    if (!summary) return;
    setGenerating(true);
    setError(null);
    try {
      const ideas = await generateAppIdeas(summary, activeDirective.prompt);
      setAppIdeas(ideas.map((idea, idx) => ({ ...idea, id: `idea-${idx}` })));
    } catch (err) {
      setError("Asset Synthesis failed.");
      console.error(err);
    } finally {
      setGenerating(false);
    }
  };

  const handleConstructIdea = async (id: string) => {
    setAppIdeas(prev => prev.map(idea => idea.id === id ? { ...idea, isConstructing: true } : idea));

    const targetIdea = appIdeas.find(i => i.id === id);
    if (!targetIdea) return;

    try {
      const result = await constructAssetSource(targetIdea);
      setAppIdeas(prev => prev.map(idea => idea.id === id ? { 
        ...idea, 
        isConstructing: false, 
        constructionComplete: true,
        synthesizedSource: result.manifest,
        constructionGuide: result.guide
      } : idea));
    } catch (err) {
      console.error("Construction failure", err);
      setAppIdeas(prev => prev.map(idea => idea.id === id ? { ...idea, isConstructing: false } : idea));
      setError("Master Architect failed to synthesize assets.");
    }
  };

  return (
    <div className="min-h-screen bg-slate-950 text-slate-200">
      <header className="border-b border-slate-800 bg-slate-900/80 backdrop-blur-xl sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3 cursor-pointer group" onClick={() => window.location.reload()}>
            <div className="p-2 bg-emerald-600 rounded-lg group-hover:rotate-12 transition-transform shadow-[0_0_15px_rgba(16,185,129,0.5)]">
              <Hammer className="w-6 h-6 text-white" />
            </div>
            <div>
              <h1 className="font-black text-xl tracking-tighter text-white uppercase italic">Construction Governor</h1>
              <p className="text-[10px] text-emerald-400 font-bold uppercase tracking-[0.2em]">Asset Build & Synthesis</p>
            </div>
          </div>

          <div className="flex items-center gap-4">
            <button 
              onClick={() => fileInputRef.current?.click()}
              className="flex items-center gap-2 px-4 py-2 bg-slate-900 hover:bg-slate-800 transition-colors rounded-lg text-sm font-bold border border-emerald-500/20 text-emerald-100 shadow-lg shadow-emerald-500/10"
            >
              <FileJson className="w-4 h-4" />
              Ingest Assets
            </button>
            <input 
              type="file" 
              ref={fileInputRef} 
              className="hidden" 
              multiple 
              // @ts-ignore
              webkitdirectory="" 
              directory="" 
              onChange={handleFileUpload} 
            />
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-8 space-y-8">
        {error && (
          <div className="p-4 bg-red-500/10 border border-red-500/20 rounded-xl flex items-center gap-3 text-red-400 animate-pulse">
            <ShieldAlert className="w-5 h-5" />
            <p className="font-bold">{error}</p>
          </div>
        )}

        {!summary && !analyzing && (
          <div className="flex flex-col items-center justify-center py-32 text-center space-y-10">
            <div className="relative">
               <div className="absolute inset-0 bg-emerald-500/20 blur-[100px] rounded-full animate-pulse"></div>
               <div className="relative w-32 h-32 bg-slate-900 rounded-[2.5rem] flex items-center justify-center border-2 border-slate-800 shadow-2xl overflow-hidden group">
                 <Hammer className="w-16 h-16 text-emerald-400 group-hover:scale-110 transition-transform" />
               </div>
            </div>
            <div className="max-w-2xl">
              <h2 className="text-6xl font-black text-white mb-6 tracking-tighter uppercase leading-none italic">Build Wealth.</h2>
              <p className="text-slate-400 text-xl leading-relaxed font-medium">The Construction Governor converts code matrix snippets into fully-realized automated wealth assets. Initialize your build core to synthesize architectural guiders.</p>
            </div>
            <button 
              onClick={() => fileInputRef.current?.click()}
              className="px-12 py-5 bg-emerald-600 hover:bg-emerald-500 transition-all rounded-[2rem] font-black text-xl shadow-2xl shadow-emerald-600/30 hover:-translate-y-1 active:scale-95 border-b-8 border-emerald-800 flex items-center gap-3 group"
            >
              <ArrowUpRight className="w-6 h-6 group-hover:rotate-45 transition-transform" />
              START ASSET SYNTHESIS
            </button>
          </div>
        )}

        {summary && !analyzing && (
